  cf_noconv: { de: "Die Anpassung hat kein Ergebnis gefunden, dem man trauen kann. Andere Startwerte oder ein anderes Modell versuchen.", en: "The fit found no result that can be trusted. Try other start values or another model." },
  cf_singular: { de: "Das Polynom ist mit diesen Daten nicht bestimmt (zu wenige verschiedene x-Werte für diesen Grad). Wähle einen kleineren Grad.", en: "The polynomial is not determined by these data (too few different x values for this degree). Choose a lower degree." },
